   <footer class="footer"><span>Little Miner · A tiny Bitcoin mining simulation</span><button class="reset" id="reset">Reset game</button></footer>
 </div>
 <div class="toast" id="toast" role="status" aria-live="polite"></div>
 <script>
+(()=>{
+  const rigs=[{name:'Hand-cranked rig',icon:'🖐️',cost:25,rate:1},{name:'GPU box',icon:'🖥️',cost:120,rate:5},{name:'ASIC miner',icon:'⚙️',cost:600,rate:30}];
+  const fresh=()=>({sats:0,total:0,levels:[0,0,0],blocks:0,last:Date.now()});
+  let game=fresh(), price=0, toastTimer;
+  try{const saved=JSON.parse(localStorage.getItem('little-miner-save'));if(saved&&Array.isArray(saved.levels)&&saved.levels.length===3&&Number.isFinite(saved.sats))game={...fresh(),...saved};}catch{}
+  const $=id=>document.getElementById(id), fmt=n=>Math.floor(n).toLocaleString('en-US'), power=()=>game.levels.reduce((sum,n,i)=>sum+n*rigs[i].rate,0), cost=i=>Math.floor(rigs[i].cost*Math.pow(1.65,game.levels[i]));
+  function save(){game.last=Date.now();try{localStorage.setItem('little-miner-save',JSON.stringify(game));}catch{}}
+  function toast(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
+  function render(){
+    const p=power(),balance=Math.floor(game.sats),usd=price?balance/1e8*price:0,progress=balance%100;
+    $('balance').textContent=fmt(balance);$('usd').textContent=`≈ $${usd.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})} in this simulation`;
+    $('walletSats').textContent=`${fmt(balance)} sats`;$('walletBtc').textContent=`${(balance/1e8).toFixed(8)} BTC`;$('rate').textContent=fmt(p);$('total').textContent=fmt(game.total);$('rigCount').textContent=fmt(game.levels.reduce((a,b)=>a+b,0));$('tapGain').textContent=`+${1+p}`;
+    $('progressText').textContent=fmt(progress);$('progress').style.width=`${progress}%`;
+    for(let i=0;i<rigs.length;i++){$(`cost${i}`).innerHTML=`${fmt(cost(i))} sats`;$(`buy${i}`).disabled=game.sats<cost(i);$(`qty${i}`).textContent=game.levels[i];}
+    const milestones=[game.total>=1,game.levels.some(x=>x>0),game.blocks>0];milestones.forEach((v,i)=>{const el=$(`badge${i+1}`);el.textContent=v?'✓':'○';el.style.color=v?'var(--mint)':'var(--muted)'});$('badgeCount').textContent=`${milestones.filter(Boolean).length} / 3`;
+  }
+  $('rigList').innerHTML=rigs.map((r,i)=>`<div class="rig"><div class="rig-icon">${r.icon}</div><div class="rig-info"><div class="rig-name">${r.name} <span style="color:var(--muted);font-size:11px">×<span id="qty${i}">0</span></span></div><div class="rig-meta">+${r.rate} sat / sec each</div></div><button class="buy" id="buy${i}">Buy<small id="cost${i}">${r.cost} sats</small></button></div>`).join('');
+  rigs.forEach((_,i)=>$(`buy${i}`).addEventListener('click',()=>{const c=cost(i);if(game.sats<c)return;game.sats-=c;game.levels[i]++;save();render();toast(`${rigs[i].name} added to your rig!`)}));
+  function award(amount,x,y){const n=Math.floor(amount);if(n<=0)return;game.sats+=n;game.total+=n;const oldBlock=Math.floor((game.sats-amount)/100),newBlock=Math.floor(game.sats/100);if(newBlock>oldBlock){game.blocks+=newBlock-oldBlock;toast('🧱 Block bonus! +100 sats');$('progress').classList.add('confetti');setTimeout(()=>$('progress').classList.remove('confetti'),450)}if(x!==undefined){const f=document.createElement('span');f.className='float';f.textContent=`+${n}`;f.style.left=`${x}px`;f.style.top=`${y}px`;document.body.appendChild(f);setTimeout(()=>f.remove(),850)}}
+  $('mine').addEventListener('click',e=>{award(1+power(),e.clientX,e.clientY);save();render()});
+  $('reset').addEventListener('click',()=>{if(!confirm('Reset your Little Miner game? Your local progress will be deleted.'))return;game=fresh();save();render();toast('Game reset — happy mining!')});
+  const elapsed=Math.max(0,Math.min((Date.now()-(game.last||Date.now()))/1000,8*60*60));if(power()&&elapsed){const earned=power()*elapsed;game.sats+=earned;game.total+=earned;const oldBlocks=game.blocks;game.blocks=Math.floor(game.sats/100);if(game.blocks>oldBlocks)setTimeout(()=>toast(`Welcome back! Your rigs earned ${fmt(earned)} sats.`),500)}
+  let then=Date.now();setInterval(()=>{const now=Date.now(),dt=Math.min((now-then)/1000,2);then=now;if(power()){const earned=power()*dt;game.sats+=earned;game.total+=earned;const b=Math.floor(game.sats/100);if(b>game.blocks){game.blocks=b;toast('🧱 Block bonus! +100 sats')} }save();render()},250);
+  async function getPrice(){try{const c=new AbortController(),timer=setTimeout(()=>c.abort(),3500),r=await fetch('https://api.coindesk.com/v1/bpi/currentprice/USD.json',{signal:c.signal});clearTimeout(timer);if(!r.ok)throw 0;const data=await r.json();price=Number(data?.bpi?.USD?.rate_float)||0;if(!price)throw 0;$('price').textContent=`$${price.toLocaleString('en-US',{maximumFractionDigits:0})}`;render()}catch{$('price').textContent='Unavailable'}}
+  render();getPrice();
+})();
 </script>
 </body>
 </html>

